import {minValueLengthValidator} from "./min-value-length-validator";

// these tests were entirely generated by claude
// all names were written by me.
describe('minValueLengthValidator', () => {
    const validator = minValueLengthValidator(3);

    it('value too short', () => {
        expect(validator('ab')).toEqual(expect.any(String));
    });

    it('value exactly like the min value', () => {
        expect(validator('abc')).toBeNull();
    });

    it('value one char longer than min value', () => {
        expect(validator('abcd')).toBeNull();
    });
});